const variant=document.body.dataset.variant;
const names={studio:'序 · 学习工作台',editorial:'间 · 校园编辑部',commons:'聚 · 社区广场'};
const nav=[['home','校园首页'],['schedule','我的课表'],['grades','成绩与学业'],['community','校园社区'],['market','二手集市'],['campus','校园服务'],['canteen','食堂与菜品'],['competition','竞赛中心'],['exams','考试 · 试卷库'],['ratings','教师 · 专业评价'],['polls','投票 · 组队'],['ai','AI 校园助手'],['messages','私信与通知'],['toolbox','工具箱'],['feedback','反馈与工单'],['profile','我的主页'],['admin','管理中心']];
const posts=[['学习交流','林间晚风','图书馆三楼，有一个属于期中周的安静角落。','靠窗的位置下午很舒服。整理了一份复习清单，也欢迎大家分享自己的学习节奏。','24','86'],['校园生活','一颗栗子','把校园的秋天，装进相册里。','银杏、操场和傍晚的风。你最喜欢校园里的哪一条路？','18','63'],['寻找搭子','慢慢来','周末一起练习英语口语吗？','每次半小时，从日常对话开始。希望找到能够互相坚持的学习伙伴。','12','35']];
let current='home',state='ready',filter='全部',query='',version=0;
document.body.innerHTML=`<a class="skip" href="#content">跳到内容</a><div class="prototype"><a href="index.html">← 方案对比</a><span>${names[variant]} / 交互原型 · 全部为演示数据</span><label>状态预览 <select id="state" aria-label="状态预览"><option value="ready">正常</option><option value="loading">加载中</option><option value="empty">空数据</option><option value="error">请求失败</option><option value="permission">未授权</option></select></label></div><header><a class="brand" href="#home"><span class="mark">理</span><b>沈理校园<small>SYLU LIVE / CAMPUS & YOU</small></b></a><div class="toplinks"><button data-page="community">发现校园</button><button data-page="schedule">学习空间</button><button data-page="campus">生活服务</button></div><label class="search"><span>⌕</span><input id="search" placeholder="搜索功能、校园话题…" aria-label="搜索功能、校园话题"></label><button class="avatar" data-page="profile" aria-label="个人主页">同</button></header><div class="layout"><aside class="sidebar"><div class="side-title">你的校园日常</div><nav>${nav.map(([id,label],i)=>`${[3,6,12].includes(i)?'<div class="nav-divider"></div>':''}<button data-page="${id}"><span class="nav-symbol">${['◫','▦','▥','◎','◇','⌘','◒','↗','▤','☆','⚑','✳','✉','⊞','☏','◉','⚙'][i]}</span>${label}</button>`).join('')}</nav><div class="side-foot"><span class="dot"></span>为沈理的每一天<br><small>连接学习，也连接彼此。</small></div></aside><main id="content" tabindex="-1"></main></div><dialog id="dialog"><form method="dialog"><button class="close" aria-label="关闭">×</button></form><div id="dialog-content"></div></dialog><div id="toast" role="status"></div>`;
const icon=(s)=>`<span class="tile-icon">${s}</span>`;
function course(){return `<div class="section-head"><h2>今天的课程</h2><button data-page="schedule">完整课表 ↗</button></div><div class="course"><span class="course-time">08:30<small>10:05</small></span><div><span class="tag">第 1–2 节</span><h3>高等数学 A</h3><p>教学楼 A · 302 / 王老师</p></div><span class="course-no">01</span></div><div class="course"><span class="course-time">14:00<small>15:35</small></span><div><span class="tag alt">第 5–6 节</span><h3>大学英语</h3><p>文体楼 · 206 / 李老师</p></div><span class="course-no">02</span></div>`}
function feed(){const items=posts.filter(p=>(filter==='全部'||p[0]===filter)&&p.join('').includes(query));return `<div class="section-head"><h2>校园正在发生</h2><button data-page="community">全部动态 ↗</button></div><div class="tabs">${['全部','学习交流','校园生活','寻找搭子'].map(t=>`<button data-filter="${t}" aria-pressed="${t===filter}">${t}</button>`).join('')}</div><div class="feed">${items.length?items.map((p,i)=>`<article class="post"><div class="post-meta"><span class="mini-avatar a${i}">${p[1][0]}</span><b>${p[1]}</b><span>· ${i+1} 小时前</span><span class="category">${p[0]}</span></div><button class="post-title" data-detail="${i}">${p[2]}</button><p>${p[3]}</p>${i===1?'<div class="autumn"><span>秋日漫游</span><b>走慢一点，<br>校园也有好风景。</b><i>SYLU / AUTUMN NOTES</i><div class="leaf l1"></div><div class="leaf l2"></div><div class="leaf l3"></div></div>':''}<div class="post-actions"><button data-like aria-pressed="false">♡ <span>${p[5]}</span></button><button data-detail="${i}">评论 ${p[4]}</button><button data-save aria-pressed="false">☆ 收藏</button></div></article>`).join(''):'<div class="state-box">没有找到相关话题，试试其他关键词。</div>'}</div>`}
function rail(){return `<aside class="rail"><section class="card date-card"><div class="eyebrow">MONDAY / NOVEMBER</div><b class="big-date">02<span>十一月</span></b><p>2026 · 秋季学期</p><div class="rule"></div><h3>给今天留一点期待。</h3><p>从一堂课、一顿饭、一次相遇开始。</p></section><section class="card"><div class="section-head"><h2>校园公告</h2><button data-page="campus">↗</button></div><div class="notice"><small>学习 · 示例公告</small><h3>图书馆学习空间使用提醒</h3><p>查看开放安排，规划你的学习时间。</p></div><div class="notice"><small>活动 · 示例公告</small><h3>校园摄影作品征集</h3><p>记录你眼中的校园日常。</p></div></section><section class="card assistant"><span class="eyebrow">YOUR CAMPUS COPILOT</span><h2>有问题，问问校园助手。</h2><p>校园信息、学习规划，<br>从一个问题开始。</p><button data-page="ai">开始对话 ↗</button></section><p class="fine">独立学生校园社区 · 设计演示<br>数据不代表学校实际通知</p></aside>`}
function home(){const hero=`<section class="hero"><div><span class="eyebrow">${variant==='editorial'?'THE CAMPUS JOURNAL / ISSUE 001':variant==='commons'?'GOOD TO SEE YOU, SYLU':'YOUR DAY, AT A GLANCE'}</span><h1>${variant==='editorial'?'校园，不止于课堂。':variant==='commons'?'在这里，遇见同频的你。':'把校园日常，安排得刚刚好。'}</h1><p>${variant==='editorial'?'读一点新鲜事，发现身边的人和生活。':variant==='commons'?'分享新鲜事，找到学习搭子，让每一次连接都有回响。':'课程、消息与校园新鲜事，在这里有序发生。'}</p><button class="primary" ${variant==='commons'?'data-publish':'data-page="schedule"'}>${variant==='commons'?'＋ 分享校园日常':'查看我的课表 ↗'}</button></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><span class="art-label">STUDY<br>LIVE<br>CONNECT.</span><span class="art-num">${variant==='editorial'?'秋':variant==='commons'?'Hi!':'02'}</span></div></section>`;const shortcuts=`<div class="shortcuts">${[['schedule','▦','查课表','下一堂课，心中有数'],['grades','▥','看成绩','回看每一步成长'],['market','◇','逛集市','让闲置继续发光'],['canteen','◒','吃什么','发现校园好味道']].map(([id,s,t,d])=>`<button data-page="${id}">${icon(s)}<span><b>${t}</b><small>${d}</small></span><span>↗</span></button>`).join('')}</div>`;return `${hero}${shortcuts}<div class="columns"><div class="main-column">${variant==='studio'?`<section class="card course-card">${course()}</section>`:''}<section class="card feed-card">${feed()}</section></div>${rail()}</div>`}
function schedule(){return `<div class="page-heading"><span class="eyebrow">MAKE ROOM FOR LEARNING</span><h1>我的课表</h1><p>秋季学期 · 演示课表，仅在当前页面展示</p></div><div class="section-head"><h2 id="week-label">第 10 周 · 11.02 — 11.08</h2><div><button data-week="-1" aria-label="上一周">←</button><button data-week="1" aria-label="下一周">→</button><button data-connect>连接教务助手</button></div></div><div class="timetable card"><div class="table-head">时间</div>${['周一','周二','周三','周四','周五'].map(x=>`<div class="table-head">${x}</div>`).join('')}${[0,1,2,3].map((r)=>`<div class="time-cell">${['08:30','10:20','14:00','15:50'][r]}</div>${[0,1,2,3,4].map((d)=>`<div class="table-cell">${(r+d)%3===0?`<button class="lesson" data-course><b>${['高等数学 A','大学英语','大学物理','程序设计'][r]}</b><span>教学楼 A · ${302+d}</span><small>第 ${r*2+1}–${r*2+2} 节</small></button>`:''}</div>`).join('')}`).join('')}</div><p class="fine">读取个人资料前需连接助手并确认身份；这里不会请求学校系统。</p>`}
function generic(){const label=nav.find(n=>n[0]===current)[1];if(current==='community')return `<div class="page-heading"><span class="eyebrow">PEOPLE MAKE THE CAMPUS</span><h1>校园社区</h1><p>有趣的日常，值得被看见。</p><button class="primary" data-publish>＋ 发布动态</button></div><div class="columns"><section class="card">${feed()}</section>${rail()}</div>`;if(current==='market')return `<div class="page-heading"><span class="eyebrow">SECOND HAND, NEW STORIES</span><h1>让好东西，遇见下一位主人。</h1><p>二手集市 / 校内闲置 · 演示商品</p></div><div class="product-grid">${[['书','考研数学复习资料','25','books'],['灯','宿舍桌面阅读灯','30','lamp'],['拍','入门羽毛球拍','45','racket'],['车','校园通勤自行车','180','bike']].map(([s,t,p,c])=>`<button class="product card" data-product="${t}"><div class="product-art ${c}">${s}</div><small>校内自提 · 九成新</small><h2>${t}</h2><b class="price">¥ ${p}</b><span>查看详情 ↗</span></button>`).join('')}</div>`;if(current==='ai')return `<div class="ai-page"><span class="ai-star">✳</span><span class="eyebrow">A LITTLE HELP FOR YOUR DAY</span><h1>今天，想了解些什么？</h1><p>校园信息、学习计划，和你一起理清思路。</p><div class="suggestions">${['帮我安排期中复习','校园里有什么服务？','怎样开始准备竞赛？'].map(t=>`<button data-prompt="${t}">${t} ↗</button>`).join('')}</div><form id="chat"><label class="sr-only" for="question">你的问题</label><input id="question" required placeholder="输入你的问题…"><button class="primary">发送 ↗</button></form><div id="answer" aria-live="polite"></div><small>这是交互演示，不连接 AI 服务；个人学业数据需另行授权。</small></div>`;return `<div class="page-heading"><span class="eyebrow">YOUR CAMPUS, CONNECTED</span><h1>${label}</h1><p>把分散的信息，变成清楚的下一步。</p></div><div class="service-grid">${(current==='grades'?['学业概览','课程成绩','学分模块','毕业缺口检查']:current==='campus'?['校园公告','校园地图','学校校历','服务信息']:current==='canteen'?['食堂一览','菜品发现','就餐评价','我的贡献']:current==='competition'?['竞赛目录','我的参赛计划','竞赛收藏','偏好设置']:current==='exams'?['考试安排','试卷检索','我的收藏','上传试卷']:current==='ratings'?['教师评价','专业评价']:current==='polls'?['校园投票','寻找队友']:current==='messages'?['我的私信','系统通知']:current==='toolbox'?['教务连接诊断','课程提醒','课表备份']:current==='profile'?['我的发布','我的收藏','浏览历史','账号设置']:current==='feedback'?['提交反馈','我的工单']:['用户管理','内容审核','公告管理','运行指标']).map((t,i)=>`<button class="card service" data-service="${t}">${icon(['▦','◎','↗','◇'][i%4])}<h2>${t}</h2><p>${['集中查看，清晰掌握','按需查找，快速定位','保留重要信息，随时回看','整理进展，安排下一步'][i%4]}</p><span>进入查看 ↗</span></button>`).join('')}</div>`}
function render(){version++;document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===current));const main=document.querySelector('main');if(state!=='ready'){const info={loading:['正在整理校园信息…','请稍候，内容即将呈现。'],empty:['这里还没有内容','从发现校园或发布第一条动态开始。'],error:['暂时无法加载','连接出现问题，你可以再次尝试。'],permission:['连接后，开启你的学习空间','确认身份后，才能读取个人课表与学业资料。']}[state];main.innerHTML=`<section class="state-box card" aria-live="polite"><span class="state-icon">${state==='loading'?'◌':state==='error'?'↻':'◎'}</span><h1>${info[0]}</h1><p>${info[1]}</p><button class="primary" ${state==='permission'?'data-connect':'data-retry'}>${state==='error'?'重新加载':state==='permission'?'了解连接方式':'返回正常预览'}</button></section>`;return}main.innerHTML=current==='home'?home():current==='schedule'?schedule():generic()}
function modal(html){document.querySelector('#dialog-content').innerHTML=html;document.querySelector('dialog').showModal()}
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('visible'),2400)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){current=b.dataset.page;query='';document.querySelector('#search').value='';state='ready';document.querySelector('#state').value='ready';render();window.scrollTo(0,0)}if(b.dataset.filter){filter=b.dataset.filter;render()}if(b.hasAttribute('data-retry')){state='ready';document.querySelector('#state').value=state;render()}if(b.hasAttribute('data-connect'))modal('<span class="eyebrow">ACADEMIC CONNECTION</span><h2>让资料读取，始终由你掌握。</h2><ol><li>安装并授权教务助手。</li><li>前往学校官网完成登录。</li><li>回到页面核对身份，再确认读取。</li></ol><p>本原型不读取真实资料，也不收集学校凭据。</p><button class="primary" data-demo-connect>模拟连接成功</button>');if(b.hasAttribute('data-demo-connect')){document.querySelector('dialog').close();state='ready';document.querySelector('#state').value=state;render();toast('演示连接已完成，未读取真实资料')}if(b.hasAttribute('data-like')){const on=b.getAttribute('aria-pressed')==='true';b.setAttribute('aria-pressed',!on);b.querySelector('span').textContent=Number(b.querySelector('span').textContent)+(on?-1:1)}if(b.hasAttribute('data-save')){const on=b.getAttribute('aria-pressed')==='true';b.setAttribute('aria-pressed',!on);b.textContent=on?'☆ 收藏':'★ 已收藏'}if(b.dataset.detail!==undefined){const p=posts[Number(b.dataset.detail)];modal(`<span class="tag">${p[0]}</span><h2>${p[2]}</h2><p>${p[3]}</p><hr><p>评论区 · 演示</p><form id="comment"><label for="comment-text">说说你的想法</label><textarea id="comment-text" required maxlength="300"></textarea><button class="primary">发布演示评论</button></form><div id="comments"></div>`)}if(b.hasAttribute('data-publish'))modal('<h2>分享你的校园日常</h2><p>内容仅用于本次页面演示，不会发布到服务器。</p><form id="publish"><label for="post-text">这一刻，想分享什么？</label><textarea id="post-text" required maxlength="500"></textarea><button class="primary">发布演示动态</button></form>');if(b.dataset.product)modal(`<h2>${b.dataset.product}</h2><p>演示商品 · 校内自提 · 价格以沟通为准</p><p>商品信息与卖家均为虚构，不能进行实际交易。</p><button class="primary" data-contact>联系演示卖家</button>`);if(b.hasAttribute('data-contact'))toast('原型演示：这里将进入与卖家的私信');if(b.hasAttribute('data-course'))modal('<span class="tag">课程详情 · 演示</span><h2>课程安排</h2><p>地点、授课教师与上课周次会在这里集中展示。</p><p>正式版本保留课表编辑、冲突提示和提醒设置。</p>');if(b.dataset.week){window.week=(window.week||10)+Number(b.dataset.week);document.querySelector('#week-label').textContent=`第 ${window.week} 周 · 演示周次`}if(b.dataset.service)modal(`<h2>${b.dataset.service}</h2><p>这是功能入口与信息层级演示，尚未连接真实业务。</p>${current==='grades'?'<p>个人学业数据需经你确认身份并授权读取。</p><button class="primary" data-connect>了解连接方式</button>':current==='admin'?'<p>正式版本需校验管理员权限，普通账号不可进入。</p>':'<p>正式版本在这里展示列表、筛选、详情及对应操作。</p>'}`);if(b.dataset.prompt)document.querySelector('#question').value=b.dataset.prompt});
document.addEventListener('submit',e=>{if(e.target.id==='publish'){e.preventDefault();toast('演示动态已完成，不会上传');document.querySelector('dialog').close()}if(e.target.id==='comment'){e.preventDefault();const p=document.createElement('p');p.textContent=document.querySelector('#comment-text').value;document.querySelector('#comments').append(p);e.target.reset()}if(e.target.id==='chat'){e.preventDefault();const token=version;const answer=document.querySelector('#answer');answer.textContent='正在整理回答…';setTimeout(()=>{if(token!==version)return;answer.textContent='演示回答：可以先明确目标，再把任务拆成每天可完成的一小步。正式版本将结合校园知识库提供回答和来源。'},650)}});
document.querySelector('#state').addEventListener('change',e=>{state=e.target.value;render()});document.querySelector('#search').addEventListener('input',e=>{query=e.target.value;const matches=nav.filter(n=>n[1].includes(query));if(query){document.querySelector('main').innerHTML=`<div class="page-heading"><h1>寻找校园里的下一步</h1><p>功能搜索</p></div><div class="service-grid">${matches.length?matches.map(([id,label])=>`<button class="card service" data-page="${id}"><h2>${label}</h2><span>进入 ↗</span></button>`).join(''):'<p>没有匹配功能，请尝试“课表”“食堂”或“社区”。</p>'}</div>`}else render()});render();
